        // M5f (decision 5): in value position, a string with a line break is literal by default; keys stay
        // double-quoted, so the value form of these rows has its own target.
        public static readonly Dictionary<string, string> LiteralValueTargets = new()
        {
            ["a\nb"] = "|-\n  a\n  b",
            ["a\n"] = "|\n  a",
            ["\na"] = "|-\n\n  a",
        };

        public static string QuotingValueTarget(string value, string target) => LiteralValueTargets.TryGetValue(value, out string? literal) ? literal : target;

